select b.id, b.reader_id, b.book_id, b.borrow_time, b.due_time, b.status, b.dept_id, r.real_name as reader_name, r.card_no, i.book_name, i.isbn from book_borrow b left join book_reader r on b.reader_id = r.id left join book_info i on b.book_id = i.id where b.status in ('0', '2') and b.del_flag = '0'
and r.card_no = #{cardNo}
and i.isbn = #{isbn}
limit 1
